custom_css:
/* 十二时辰·未·荣光 · 十二时辰 其八 · 未时 13:00–15:00 · 柔光 · by if love */
/* 十二时辰·未·荣光 · tokens  —  by if love */
@import url("https://fonts.googleapis.com/css2?family=Liu+Jian+Mao+Cao&family=LXGW+WenKai+TC:wght@400;700&family=Great+Vibes&display=swap");

:root {
  /* 杏白底 */
  --wei-bg: #FBF3E3;
  --wei-surface: rgba(255, 250, 238, 0.94);
  --wei-surface-2: rgba(255, 246, 226, 0.88);
  --wei-field: #FFFBF1;

  /* 墨与金 */
  --wei-ink: #4E3B22;
  --wei-ink-2: #6E5530;
  --wei-ink-3: #A07E44;
  --wei-ink-disabled: #C7B08A;
  --wei-gold: #B07A2A;
  --wei-gold-deep: #8A4F14;
  --wei-gold-bright: #E9B65A;
  --wei-gold-grad: linear-gradient(135deg, #F1C56A, #D99A3A);
  --wei-line: rgba(190, 140, 60, 0.38);
  --wei-line-soft: rgba(190, 140, 60, 0.2);

  /* 用户青 */
  --wei-jade: #3F6E5C;
  --wei-jade-ink: #34463C;
  --wei-jade-soft: #5E9E86;

  /* 语义 */
  --wei-danger: #B5482E;
  --wei-ok: #5E8F5A;

  /* 光与影（只用暖金光，不用黑影） */
  --wei-glow: 0 0 8px rgba(246, 200, 100, 0.75);
  --wei-glow-soft: 0 0 14px rgba(255, 220, 140, 0.9);
  --wei-lift: 0 10px 26px -14px rgba(150, 100, 30, 0.45);
  --wei-focus: 0 0 0 2px rgba(233, 182, 90, 0.85);

  /* 字体：奔马 */
  --wei-f-title: "Liu Jian Mao Cao", "KaiTi", "STKaiti", serif;
  --wei-f-body: "LXGW WenKai TC", "LXGW WenKai", "KaiTi", "STKaiti", "Songti SC", serif;
  --wei-f-en: "Great Vibes", "Snell Roundhand", cursive;

  /* 图片（每张只内嵌一次） */
  --wei-img-sun: url("data:image/webp;base64,");
  --wei-img-sunbg: url("data:image/webp;base64,");
  --wei-img-banner: url("data:image/webp;base64,");
  --wei-img-wind: url("data:image/webp;base64,");
  --wei-img-frame: url("data:image/webp;base64,");

  /* 尺寸 */
  --wei-av-w: 132px;
  --wei-av-h: 198px;
  --wei-head-h: 206px;
  --st-theme-mobile-reading-width: 100%;
  --st-theme-mobile-reading-padding: 4px;

  /* 覆盖酒馆主题变量（同色值也写进 JSON 颜色字段） */
  --SmartThemeBodyColor: var(--wei-ink);
  --SmartThemeEmColor: #9C6A22;
  --SmartThemeQuoteColor: var(--wei-gold);
  --SmartThemeUnderlineColor: var(--wei-gold-deep);
  --SmartThemeBorderColor: var(--wei-line);
  --SmartThemeCheckboxTickColor: #FFFFFF;
  --mainFontFamily: var(--wei-f-body);
  --interactable-outline-color: var(--wei-gold-bright);
}

/* kernel · 滚动条外观隐藏（不改变滚动行为） */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* chat-layout · 主聊天：杏白底、角色楼「左风右像」、用户楼「左像右日」 */

/* —— 背景：纯杏白 —— */
body {
  background-color: var(--wei-bg) !important;
  font-family: var(--wei-f-body);
}
#bg1,
#bg_custom {
  background-image: none !important;
  background-color: var(--wei-bg) !important;
}
#chat {
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* —— 楼层骨架 —— 头像改为绝对定位，正文铺满全宽（高风险：position:absolute） */
#chat .mes[is_system="false"] {
  isolation: isolate;
  padding: 16px 14px 14px;
  margin-bottom: 22px;
  background: transparent;
  border: 0;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  position: absolute;
  top: 8px;
  width: var(--wei-av-w);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  z-index: 1;
}
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper { right: 6px; }
#chat .mes[is_user="true"] > .mesAvatarWrapper { left: 6px; }

#chat .mes[is_system="false"] > .mes_block {
  position: relative;
  z-index: 1;
  min-width: 0;
  padding: 0;
}

/* 抬头区：留出头像的位置 */
#chat .mes[is_system="false"] .ch_name {
  min-height: var(--wei-head-h);
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 6px;
  padding-top: 18px;
}
#chat .mes[is_user="false"][is_system="false"] .ch_name { padding-right: calc(var(--wei-av-w) + 8px); }
#chat .mes[is_user="true"] .ch_name {
  padding-left: calc(var(--wei-av-w) + 8px);
  align-items: flex-end;
  text-align: right;
}
#chat .mes[is_system="false"] .ch_name > .flex-container.flex1 { flex: 0 0 auto; width: 100%; }
#chat .mes[is_user="true"] .ch_name > .flex-container.flex1 { justify-content: flex-end; }

/* 名字 + 时辰签：时间放到名字上方 */
#chat .mes[is_system="false"] .ch_name .alignItemsBaseline {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
#chat .mes[is_user="true"] .ch_name .alignItemsBaseline { align-items: flex-end; }

#chat .mes[is_system="false"] .name_text {
  font-family: var(--wei-f-title);
  font-size: calc(var(--mainFontSize) * 2.7);
  line-height: 1.15;
  letter-spacing: 0.12em;
  font-weight: 400;
  color: var(--wei-gold-deep);
  text-shadow: var(--wei-glow-soft);
}
#chat .mes[is_user="true"] .name_text {
  color: var(--wei-jade);
  text-shadow: 0 0 12px #FFFFFF;
}

#chat .mes[is_system="false"] .timestamp {
  order: -1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 3px 2px;
  font-size: 0.72em;
  letter-spacing: 0.2em;
  color: var(--wei-ink-2);
  opacity: 1;
  background:
    linear-gradient(90deg, transparent, var(--wei-line), transparent) top / 100% 1px no-repeat,
    linear-gradient(90deg, transparent, var(--wei-line), transparent) bottom / 100% 1px no-repeat;
}
#chat .mes[is_system="false"] .timestamp::before {
  content: "";
  width: 14px;
  height: 14px;
  flex: none;
  background: var(--wei-img-sun) center / contain no-repeat;
  pointer-events: none;
}
#chat .mes .mes_ghost { color: var(--wei-ink-3); }

/* —— 角色楼：左侧风（逐日） —— */
#chat .mes[is_user="false"][is_system="false"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: min(80%, 440px);
  height: calc(var(--wei-head-h) + 34px);
  background: var(--wei-img-wind) left top / auto 100% no-repeat;
  -webkit-mask-image: linear-gradient(#000 62%, transparent);
  mask-image: linear-gradient(#000 62%, transparent);
  z-index: -1;
  pointer-events: none;
}

/* —— 用户楼：右侧烈日 —— */
#chat .mes[is_user="true"]::before {
  content: "";
  position: absolute;
  right: 0;
  top: -10px;
  width: min(86%, 470px);
  height: calc(var(--wei-head-h) + 50px);
  background: var(--wei-img-sunbg) right center / auto 120% no-repeat;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 45%), linear-gradient(transparent, #000 20%, #000 78%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(90deg, transparent 0%, #000 45%), linear-gradient(transparent, #000 20%, #000 78%, transparent);
  mask-composite: intersect;
  z-index: -1;
  pointer-events: none;
}

/* —— 头像 —— */
#chat .mes[is_system="false"] .mesAvatarWrapper .avatar {
  position: relative;
  width: var(--wei-av-w);
  height: var(--wei-av-h);
  border-radius: 0;
  overflow: visible;
  background: transparent;
  box-shadow: none;
  flex: none;
}
#chat .mes[is_system="false"] .mesAvatarWrapper .avatar img {
  position: absolute;
  inset: 14% 12%;
  width: 76%;
  height: 72%;
  object-fit: cover;
  object-position: center top;
  border-radius: 999px 999px 8px 8px;
  border: 0;
  box-shadow: none;
}
/* 角色：拱门框（盖在头像上，不吃点击） */
#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper .avatar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--wei-img-frame) center / 100% 100% no-repeat;
  pointer-events: none;
}
/* 用户：头像虚影，向下渐隐 */
#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
  inset: 4% 6% 10%;
  width: 88%;
  height: 86%;
  -webkit-mask-image: linear-gradient(#000 55%, transparent 100%);
  mask-image: linear-gradient(#000 55%, transparent 100%);
  opacity: 0.92;
}

/* 楼层号日轮 / token / 计时 */
#chat .mes .mesIDDisplay {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  margin-top: -6px;
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #FFFFFF;
  text-shadow: 0 0 3px rgba(150, 90, 20, 0.95);
  background: var(--wei-img-sun) center / contain no-repeat;
  opacity: 1;
}
#chat .mes .tokenCounterDisplay,
#chat .mes .mes_timer {
  font-size: 0.68em;
  letter-spacing: 0.08em;
  color: var(--wei-ink-3);
  opacity: 1;
}

/* —— 正文 —— */
#chat .mes[is_system="false"] .mes_text {
  padding: 4px 4px 0;
  color: var(--wei-ink);
  font-family: var(--wei-f-body);
  line-height: 1.95;
}
#chat .mes[is_user="true"] .mes_text { color: var(--wei-jade-ink); }

/* 狂草首字 */
#chat .mes[is_system="false"] .mes_text > p:first-child::first-letter {
  float: left;
  font-family: var(--wei-f-title);
  font-size: 3.3em;
  line-height: 0.86;
  margin: 0.12em 0.18em 0 0;
  color: var(--wei-gold);
  text-shadow: var(--wei-glow-soft);
}
#chat .mes[is_user="true"] .mes_text > p:first-child::first-letter {
  color: var(--wei-jade-soft);
  text-shadow: 0 0 12px #FFFFFF;
}

/* —— 楼层按钮：描金细圈 —— */
#chat .mes .mes_buttons {
  margin-top: auto;
  gap: 6px;
  opacity: 1;
  filter: none;
}
#chat .mes .mes_buttons .mes_button,
#chat .mes .extraMesButtons .mes_button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 50%;
  font-size: 12px;
  color: var(--wei-gold);
  opacity: 1;
  filter: none;
  background: radial-gradient(circle, rgba(255, 250, 236, 0.96) 56%, rgba(255, 236, 190, 0) 72%);
  box-shadow: inset 0 0 0 1px var(--wei-line);
  transition: box-shadow 0.2s, color 0.2s;
}
#chat .mes .mes_button:hover { color: var(--wei-gold-deep); box-shadow: inset 0 0 0 1px var(--wei-gold-bright), var(--wei-glow); }
#chat .mes .mes_button:focus-visible { outline: none; box-shadow: var(--wei-focus); }

/* 翻页 */
#chat .mes .swipe_left,
#chat .mes .swipe_right {
  color: var(--wei-gold);
  opacity: 0.85;
  filter: none;
}
#chat .mes .swipe_left:hover,
#chat .mes .swipe_right:hover { opacity: 1; text-shadow: var(--wei-glow); }
#chat .mes .swipes-counter {
  color: var(--wei-ink-3);
  font-variant-numeric: tabular-nums;
  opacity: 1;
}

/* —— 编辑态 —— */
#chat .mes .mes_edit_buttons { gap: 6px; }
#chat .mes .mes_edit_buttons .menu_button {
  width: 30px;
  height: 30px;
  padding: 0;
  margin: 0;
  border-radius: 50%;
  border: 0;
  color: var(--wei-gold);
  filter: none;
  opacity: 1;
  background: radial-gradient(circle, rgba(255, 250, 236, 0.96) 56%, rgba(255, 236, 190, 0) 72%);
  box-shadow: inset 0 0 0 1px var(--wei-line);
}
#chat .mes .mes_edit_buttons .mes_edit_done { color: #FFFFFF; background: var(--wei-gold-grad); box-shadow: var(--wei-glow); }
#chat .mes .mes_edit_buttons .mes_edit_delete { color: var(--wei-danger); }
#chat .mes .mes_edit_buttons .menu_button:hover { box-shadow: inset 0 0 0 1px var(--wei-gold-bright), var(--wei-glow); }
#chat .mes .edit_textarea,
#chat .mes .reasoning_edit_textarea {
  color: var(--wei-ink);
  background: rgba(255, 251, 240, 0.95);
  border: 1px solid var(--wei-line);
  border-radius: 4px;
  box-shadow: var(--wei-lift);
  font-family: var(--wei-f-body);
  line-height: 1.9;
  padding: 10px 12px;
}
#chat .mes .edit_textarea:focus,
#chat .mes .reasoning_edit_textarea:focus { outline: none; box-shadow: var(--wei-focus), var(--wei-lift); }

/* 删除模式勾选、选中态 */
#chat .mes.selected { background-color: rgba(241, 197, 106, 0.18); }
#chat .mes .del_checkbox { accent-color: var(--wei-gold); }

/* —— 系统楼（欢迎等）：不加头部装饰，只统一墨色 —— */
#chat .mes[is_system="true"] .mes_text { color: var(--wei-ink-2); }
#chat .mes[is_system="true"] .name_text {
  font-family: var(--wei-f-title);
  color: var(--wei-gold-deep);
}

/* —— 手机 —— */
@media (max-width: 700px) {
  :root {
    --wei-av-w: 104px;
    --wei-av-h: 156px;
    --wei-head-h: 168px;
  }
  #chat .mes[is_system="false"] { padding: 12px 8px 10px; }
  #chat .mes[is_system="false"] .name_text { font-size: calc(var(--mainFontSize) * 2.2); }
  #chat .mes[is_user="false"][is_system="false"]::before { width: 88%; }
  #chat .mes[is_user="true"]::before { width: 96%; }
  #chat .mes[is_system="false"] > .mes_block > .mes_text {
    inline-size: min(100%, var(--st-theme-mobile-reading-width));
    max-inline-size: 100%;
    margin-inline: auto !important;
    padding-inline: var(--st-theme-mobile-reading-padding) !important;
    box-sizing: border-box;
  }
}

/* full-text · 只作用于 #chat .mes_text 内的语义内容 */
#chat .mes_text em,
#chat .mes_text i { color: #9C6A22; }
#chat .mes_text q,
#chat .mes_text q::before,
#chat .mes_text q::after { color: var(--wei-gold); }
#chat .mes_text u { color: var(--wei-gold-deep); text-decoration-color: var(--wei-gold-bright); }
#chat .mes_text strong,
#chat .mes_text b { color: var(--wei-gold-deep); }
#chat .mes_text a { color: var(--wei-jade); text-decoration-color: var(--wei-line); }

#chat .mes_text blockquote {
  margin: 0.6em 0;
  padding: 0.5em 1em;
  color: var(--wei-ink-2);
  background: rgba(241, 197, 106, 0.12);
  border: 0;
  border-radius: 4px;
  box-shadow: inset 0 0 0 1px var(--wei-line-soft);
}
#chat .mes_text hr {
  border: 0;
  height: 1px;
  margin: 1em 0;
  background: linear-gradient(90deg, transparent, var(--wei-line), transparent);
}

/* 行内代码 */
#chat .mes_text code {
  color: var(--wei-gold-deep);
  background: rgba(241, 197, 106, 0.16);
  border: 0;
  border-radius: 3px;
  padding: 0 0.3em;
  font-family: ui-monospace, "Cascadia Mono", Menlo, monospace;
}
/* 代码块：外 pre、内 code.hljs、hljs 子 token 分开处理，保留横向滚动 */
#chat .mes_text pre {
  background: #FFF8E8;
  border: 1px solid var(--wei-line-soft);
  border-radius: 6px;
  box-shadow: none;
  overflow-x: auto;
}
#chat .mes_text pre code,
#chat .mes_text pre code.hljs {
  display: block;
  color: var(--wei-ink);
  background: transparent;
  padding: 0.8em 1em;
}
#chat .mes_text pre code.hljs .hljs-keyword,
#chat .mes_text pre code.hljs .hljs-built_in,
#chat .mes_text pre code.hljs .hljs-selector-tag { color: #A0521C; }
#chat .mes_text pre code.hljs .hljs-string,
#chat .mes_text pre code.hljs .hljs-attr { color: #3F6E5C; }
#chat .mes_text pre code.hljs .hljs-number,
#chat .mes_text pre code.hljs .hljs-literal { color: #B07A2A; }
#chat .mes_text pre code.hljs .hljs-comment { color: #A89474; font-style: italic; }
#chat .mes_text pre code.hljs .hljs-title,
#chat .mes_text pre code.hljs .hljs-function { color: #8A4F14; }
#chat .mes_text ::selection,
#chat .mes_text pre ::selection { background: rgba(241, 197, 106, 0.45); color: var(--wei-ink); }

#chat .mes_text table { border-collapse: collapse; }
#chat .mes_text th,
#chat .mes_text td { border: 1px solid var(--wei-line-soft); padding: 4px 8px; }
#chat .mes_text th { color: var(--wei-gold-deep); background: rgba(241, 197, 106, 0.14); }

/* 思维链 */
#chat .mes_reasoning_details {
  border: 0;
  border-radius: 6px;
  background: rgba(255, 246, 226, 0.7);
  box-shadow: inset 0 0 0 1px var(--wei-line-soft);
}
#chat .mes_reasoning_summary,
#chat .mes_reasoning_header_title { color: var(--wei-ink-3); opacity: 1; filter: none; }
#chat .mes_reasoning_arrow { color: var(--wei-gold); }
#chat .mes_reasoning { color: var(--wei-ink-2); opacity: 1; }

/* W02 顶栏 · 奔马横幅 + 九个小物 */
#top-bar {
  background: var(--wei-img-banner) center 42% / cover no-repeat, var(--wei-bg);
  box-shadow: 0 6px 18px -12px rgba(150, 100, 30, 0.45);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
#top-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(rgba(251, 243, 227, 0.35), rgba(251, 243, 227, 0.55));
  pointer-events: none;
}

/* 图标：关掉 Font Awesome 的 ::before 字形，换成「小日轮 + 白描小物」；点击宿主不动 */
#top-settings-holder .drawer-icon {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  font-size: 0;
  color: transparent;
  filter: none;
  transition: opacity 0.2s, filter 0.2s;
}
#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: block;
  width: 30px;
  height: 30px;
  background-position: center, center;
  background-size: 17px 17px, contain;
  background-repeat: no-repeat;
  background-image: var(--wei-img-sun);
  pointer-events: none;
}
#ai-config-button .drawer-icon::before { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cg stroke=%22%238A4F14%22 stroke-opacity=%22.55%22 stroke-width=%223.2%22%3E%3Cpath d=%22M7 21 L16 5%22/%3E%3Cpath d=%22M16 5 C14 3 17 2 18 4 C19 6 16 7 16 5Z%22/%3E%3Cpath d=%22M11 13 l2 1.2%22/%3E%3C/g%3E%3Cg stroke=%22%23FFFDF6%22 stroke-width=%221.6%22%3E%3Cpath d=%22M7 21 L16 5%22/%3E%3Cpath d=%22M16 5 C14 3 17 2 18 4 C19 6 16 7 16 5Z%22/%3E%3Cpath d=%22M11 13 l2 1.2%22/%3E%3C/g%3E%3C/svg%3E"), var(--wei-img-sun); }
#sys-settings-button .drawer-icon::before { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cg stroke=%22%238A4F14%22 stroke-opacity=%22.55%22 stroke-width=%223.2%22%3E%3Cpath d=%22M5 12 C5 7 11 7 12 12 C13 17 19 17 19 12 C19 7 13 7 12 12 C11 17 5 17 5 12Z%22/%3E%3C/g%3E%3Cg stroke=%22%23FFFDF6%22 stroke-width=%221.6%22%3E%3Cpath d=%22M5 12 C5 7 11 7 12 12 C13 17 19 17 19 12 C19 7 13 7 12 12 C11 17 5 17 5 12Z%22/%3E%3C/g%3E%3C/svg%3E"), var(--wei-img-sun); }
#advanced-formatting-button .drawer-icon::before { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cg stroke=%22%238A4F14%22 stroke-opacity=%22.55%22 stroke-width=%223.2%22%3E%3Cpath d=%22M16 4 L9 15%22/%3E%3Cpath d=%22M9 15 C6 16 5 19 6 21 C8 21 11 19 11 16Z%22/%3E%3Cpath d=%22M15 3.5 l2.2 1.4%22/%3E%3C/g%3E%3Cg stroke=%22%23FFFDF6%22 stroke-width=%221.6%22%3E%3Cpath d=%22M16 4 L9 15%22/%3E%3Cpath d=%22M9 15 C6 16 5 19 6 21 C8 21 11 19 11 16Z%22/%3E%3Cpath d=%22M15 3.5 l2.2 1.4%22/%3E%3C/g%3E%3C/svg%3E"), var(--wei-img-sun); }
