#top-settings-holder .drawer-icon.closedIcon { opacity: 0.72; }
#top-settings-holder .drawer-icon.closedIcon:hover { opacity: 1; filter: drop-shadow(0 0 6px rgba(246, 200, 100, 0.85)); }
#top-settings-holder .drawer-icon.openIcon {
  opacity: 1;
  filter: drop-shadow(0 0 8px rgba(246, 190, 80, 0.95));
}
#top-settings-holder .drawer-icon:focus-visible { outline: none; box-shadow: var(--wei-focus); border-radius: 50%; }

/* API 未连接：图标类会换成 plug-circle-exclamation，此时日轮褪色以示区别 */
#API-status-top.fa-plug-circle-exclamation { filter: saturate(0.55); }

/* W03 输入区 · 杏白条 + 日轮发送键 */
#send_form {
  background: var(--wei-surface);
  border: 1px solid var(--wei-line-soft);
  border-radius: 18px;
  box-shadow: var(--wei-lift);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
#send_form.no-connection { background: var(--wei-surface-2); }
#send_textarea {
  color: var(--wei-ink);
  background: transparent;
  font-family: var(--wei-f-body);
  letter-spacing: 0.04em;
}
#send_textarea::placeholder { color: var(--wei-ink-3); opacity: 1; letter-spacing: 0.18em; }

#leftSendForm > div,
#rightSendForm > div {
  color: var(--wei-gold);
  opacity: 0.9;
  filter: none;
}
#leftSendForm > div:hover,
#rightSendForm > div:hover { opacity: 1; text-shadow: var(--wei-glow); }

/* 发送：只换 ::before 的字形为日轮，宿主保留点击/键盘 */
#send_but {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  font-size: 0;
  color: transparent;
  opacity: 1;
  filter: none;
}
#send_but::before {
  content: "" !important;
  display: block;
  width: 36px;
  height: 36px;
  background: var(--wei-img-sun) center / contain no-repeat;
  filter: drop-shadow(0 0 6px rgba(246, 200, 100, 0.8));
  transition: transform 0.2s;
  pointer-events: none;
}
#send_but:hover::before { transform: rotate(18deg) scale(1.06); }
#send_but:focus-visible { outline: none; box-shadow: var(--wei-focus); border-radius: 50%; }
#mes_stop { color: var(--wei-danger); opacity: 1; filter: none; }

/* 快捷回复 */
#qr--bar .qr--button,
#quickReplies .qr--button {
  color: var(--wei-gold-deep);
  background: var(--wei-surface-2);
  border: 0;
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px var(--wei-line);
  letter-spacing: 0.12em;
  filter: none;
  opacity: 1;
}
#qr--bar .qr--button:hover,
#quickReplies .qr--button:hover { color: #FFFFFF; background: var(--wei-gold-grad); box-shadow: var(--wei-glow); }

/* 输入区弹出菜单（汉堡、魔杖） */
#options .options-content,
#extensionsMenu {
  color: var(--wei-ink);
  background: rgba(255, 250, 238, 0.98);
  border: 1px solid var(--wei-line-soft);
  border-radius: 10px;
  box-shadow: var(--wei-lift);
  backdrop-filter: none;
}
#options .options-content a,
#extensionsMenu .list-group-item { color: var(--wei-ink); opacity: 1; filter: none; }
#options .options-content a:hover,
#extensionsMenu .list-group-item:hover { color: var(--wei-gold-deep); background: rgba(241, 197, 106, 0.18); }
#options .options-content a > i,
#extensionsMenu .list-group-item > i,
#extensionsMenu .extensionsMenuExtensionButton { color: var(--wei-gold); }

/* W04–W12 抽屉与面板 · 共用表面 + 各窗口根节点分别限定 */

/* 抽屉表面：左（回复配置）、右（角色）、顶栏各下拉窗口 */
#left-nav-panel,
#right-nav-panel,
#top-settings-holder .drawer-content {
  color: var(--wei-ink);
  background-color: var(--wei-surface);
  border: 1px solid var(--wei-line-soft);
  border-radius: 14px;
  box-shadow: var(--wei-lift);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  font-family: var(--wei-f-body);
}

/* 抽屉标题：狂草 + 小日轮 */
#left-nav-panel h3,
#right-nav-panel h3,
#top-settings-holder .drawer-content h3,
#top-settings-holder .drawer-content h4 {
  font-family: var(--wei-f-title);
  font-weight: 400;
  letter-spacing: 0.14em;
  color: var(--wei-gold-deep);
}
#left-nav-panel .inline-drawer-header,
#right-nav-panel .inline-drawer-header,
#top-settings-holder .drawer-content .inline-drawer-header {
  color: var(--wei-ink);
  padding: 6px 2px;
  background:
    linear-gradient(90deg, transparent, var(--wei-line-soft), transparent) bottom / 100% 1px no-repeat;
}
#left-nav-panel .inline-drawer-icon,
#right-nav-panel .inline-drawer-icon,
#top-settings-holder .drawer-content .inline-drawer-icon { color: var(--wei-gold); opacity: 1; filter: none; }

/* 通用按钮 .menu_button（限定在主界面各窗口内） */
#left-nav-panel .menu_button,
#right-nav-panel .menu_button,
#top-settings-holder .drawer-content .menu_button,
#send_form .menu_button,
.popup .menu_button {
  color: var(--wei-gold-deep);
  background-color: var(--wei-field);
  border: 1px solid var(--wei-line);
  border-radius: 999px;
  padding: 4px 12px;
  filter: none;
  opacity: 1;
  box-shadow: none;
  transition: background-color 0.2s, box-shadow 0.2s, color 0.2s;
}
#left-nav-panel .menu_button:hover,
#right-nav-panel .menu_button:hover,
#top-settings-holder .drawer-content .menu_button:hover,
#send_form .menu_button:hover,
.popup .menu_button:hover {
  color: #FFFFFF;
  background: var(--wei-gold-grad);
  border-color: transparent;
  box-shadow: var(--wei-glow);
}
#left-nav-panel .menu_button:focus-visible,
#right-nav-panel .menu_button:focus-visible,
#top-settings-holder .drawer-content .menu_button:focus-visible,
.popup .menu_button:focus-visible { outline: none; box-shadow: var(--wei-focus); }
#left-nav-panel .menu_button.toggleEnabled,
#right-nav-panel .menu_button.toggleEnabled,
#top-settings-holder .drawer-content .menu_button.toggleEnabled,
#left-nav-panel .menu_button.active,
#top-settings-holder .drawer-content .menu_button.active {
  color: #FFFFFF;
  background: var(--wei-gold-grad);
  border-color: transparent;
}
#left-nav-panel .menu_button.disabled,
#right-nav-panel .menu_button.disabled,
#top-settings-holder .drawer-content .menu_button.disabled,
#left-nav-panel .menu_button:disabled,
#top-settings-holder .drawer-content .menu_button:disabled {
  color: var(--wei-ink-disabled);
  background: var(--wei-field);
  border-color: var(--wei-line-soft);
  box-shadow: none;
  cursor: not-allowed;
}
.popup .menu_button.popup-button-ok {
  color: #FFFFFF;
  background: var(--wei-gold-grad);
  border-color: transparent;
}

/* 文本框 / 下拉 / 多行 */
#left-nav-panel .text_pole,
#right-nav-panel .text_pole,
#top-settings-holder .drawer-content .text_pole,
.popup .text_pole,
#left-nav-panel select,
#right-nav-panel select,
#top-settings-holder .drawer-content select,
#left-nav-panel textarea,
#right-nav-panel textarea,
#top-settings-holder .drawer-content textarea {
  color: var(--wei-ink);
  background-color: var(--wei-field);
  border: 1px solid var(--wei-line);
  border-radius: 6px;
  box-shadow: none;
  font-family: var(--wei-f-body);
}
#left-nav-panel .text_pole:focus,
#right-nav-panel .text_pole:focus,
#top-settings-holder .drawer-content .text_pole:focus,
.popup .text_pole:focus,
#left-nav-panel select:focus,
#top-settings-holder .drawer-content select:focus,
#left-nav-panel textarea:focus,
#right-nav-panel textarea:focus,
#top-settings-holder .drawer-content textarea:focus { outline: none; border-color: var(--wei-gold-bright); box-shadow: var(--wei-focus); }
#left-nav-panel ::placeholder,
#right-nav-panel ::placeholder,
#top-settings-holder .drawer-content ::placeholder { color: var(--wei-ink-3); opacity: 1; }
#left-nav-panel option,
#top-settings-holder .drawer-content option { color: var(--wei-ink); background: var(--wei-field); }

/* 复选框：保留官方 ::before 勾形绘制链，只换颜色 */
#left-nav-panel input[type="checkbox"],
#right-nav-panel input[type="checkbox"],
#top-settings-holder .drawer-content input[type="checkbox"],
.popup input[type="checkbox"] {
  background-color: var(--wei-field);
  border: 1px solid var(--wei-line);
  box-shadow: none;
  filter: none;
}
#left-nav-panel input[type="checkbox"]:checked,
#right-nav-panel input[type="checkbox"]:checked,
#top-settings-holder .drawer-content input[type="checkbox"]:checked,
.popup input[type="checkbox"]:checked {
  background: var(--wei-gold-grad);
  border-color: transparent;
}
#left-nav-panel input[type="checkbox"]::before,
#right-nav-panel input[type="checkbox"]::before,
#top-settings-holder .drawer-content input[type="checkbox"]::before,
.popup input[type="checkbox"]::before { box-shadow: inset 1em 1em #FFFFFF; }
#left-nav-panel input[type="checkbox"]:disabled,
#top-settings-holder .drawer-content input[type="checkbox"]:disabled { opacity: 0.55; }
#left-nav-panel input[type="radio"],
#top-settings-holder .drawer-content input[type="radio"] { accent-color: var(--wei-gold); }

/* 滑块：金线轨道 + 日轮拇指 */
#left-nav-panel input[type="range"],
#top-settings-holder .drawer-content input[type="range"] {
  height: 4px;
  background: linear-gradient(90deg, #F1C56A, #D99A3A);
  border-radius: 4px;
  box-shadow: none;
  filter: none;
}
#left-nav-panel input[type="range"]::-webkit-slider-thumb,
#top-settings-holder .drawer-content input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: var(--wei-img-sun) center / contain no-repeat;
  box-shadow: var(--wei-glow);
}
#left-nav-panel input[type="range"]::-moz-range-thumb,
#top-settings-holder .drawer-content input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: var(--wei-img-sun) center / contain no-repeat;
}
#left-nav-panel input[type="range"]:hover,
#top-settings-holder .drawer-content input[type="range"]:hover { filter: none; }

/* 提示词管理器 */
#completion_prompt_manager .completion_prompt_manager_prompt {
  color: var(--wei-ink);
  background: transparent;
  border-color: var(--wei-line-soft);
  opacity: 1;
  filter: none;
}
#completion_prompt_manager .completion_prompt_manager_prompt_disabled { color: var(--wei-ink-disabled); opacity: 1; filter: none; }
#completion_prompt_manager .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled span { color: var(--wei-ink-disabled); opacity: 1; }
#completion_prompt_manager .prompt-manager-toggle-action,
#completion_prompt_manager .prompt-manager-edit-action,
#completion_prompt_manager .prompt-manager-detach-action,
#completion_prompt_manager .prompt-manager-inspect-action { color: var(--wei-gold); opacity: 1; filter: none; }
#completion_prompt_manager .fa-toggle-off { color: var(--wei-ink-disabled); }
#completion_prompt_manager .completion_prompt_manager_prompt:focus-within { box-shadow: var(--wei-focus); }

/* 角色列表 */
#right-nav-panel .character_select,
#right-nav-panel .group_select {
  color: var(--wei-ink);
  border-radius: 10px;
  transition: background-color 0.2s;
}
#right-nav-panel .character_select:hover,
#right-nav-panel .group_select:hover { background: rgba(241, 197, 106, 0.16); }
#right-nav-panel .character_select.is_fav .ch_name,
#right-nav-panel .character_select .ch_name { color: var(--wei-ink); }
#right-nav-panel .character_select .avatar img,
#right-nav-panel .group_select .avatar img {
  border-radius: 999px 999px 6px 6px;
  box-shadow: 0 0 0 1px var(--wei-line);
}
#right-nav-panel .character_select .ch_description,
#right-nav-panel .character_select small { color: var(--wei-ink-3); opacity: 1; }

/* 角色卡标签（与 Select2 标签分开） */
#right-nav-panel .tags.tags_inline .tag,
#right-nav-panel .tag {
  color: var(--wei-gold-deep);
  background: rgba(241, 197, 106, 0.2);
  border: 0;
  border-radius: 999px;
  opacity: 1;
  filter: none;
}
#right-nav-panel .tag.selected { color: #FFFFFF; background: var(--wei-gold-grad); }
#right-nav-panel .tag.excluded { color: var(--wei-danger); background: rgba(181, 72, 46, 0.12); }
#right-nav-panel .tag .tag_remove { color: inherit; opacity: 0.8; }

/* Select2（运行时挂载在 body 下的下拉） */
.select2-container .select2-selection,
.select2-container .select2-dropdown {
  color: var(--wei-ink);
  background-color: var(--wei-field);
  border: 1px solid var(--wei-line);
  box-shadow: none;
}
.select2-container .select2-selection__choice {
  color: var(--wei-gold-deep);
  background-color: rgba(241, 197, 106, 0.22);
  border: 0;
  border-radius: 999px;
}
.select2-container .select2-results__option--highlighted { color: #FFFFFF; background: var(--wei-gold-grad); }
.select2-container .select2-search__field { color: var(--wei-ink); }

/* W13 弹窗 / 提示 / 菜单 */
.popup {
  color: var(--wei-ink);
  background: radial-gradient(120% 60% at 50% 0%, #FFF1CC, #FFFAEF 62%);
  border: 1px solid var(--wei-line);
  border-radius: 12px;
  box-shadow: 0 24px 50px -16px rgba(120, 80, 20, 0.55);
  font-family: var(--wei-f-body);
}
.popup::backdrop { background: rgba(120, 90, 40, 0.28); }
.popup h3,
.popup .popup-content h3 {
  font-family: var(--wei-f-title);
  font-weight: 400;
  letter-spacing: 0.14em;
  color: var(--wei-gold-deep);
}
.popup .popup-content { color: var(--wei-ink-2); }

/* 提示条 */
body #toast-container > div {
  color: var(--wei-ink-2);
  background-color: rgba(255, 250, 236, 0.98);
  background-image: none;
  border: 0;
  border-radius: 999px;
  box-shadow: 0 8px 20px -8px rgba(120, 80, 20, 0.45);
  opacity: 1;
  font-family: var(--wei-f-body);
}
body #toast-container > .toast-success { box-shadow: 0 8px 20px -8px rgba(120, 80, 20, 0.45), inset 0 0 0 1px rgba(94, 143, 90, 0.5); }
body #toast-container > .toast-error { color: var(--wei-danger); box-shadow: 0 8px 20px -8px rgba(120, 80, 20, 0.45), inset 0 0 0 1px rgba(181, 72, 46, 0.5); }
body #toast-container > .toast-warning { box-shadow: 0 8px 20px -8px rgba(120, 80, 20, 0.45), inset 0 0 0 1px var(--wei-gold-bright); }
body #toast-container .toast-title { color: var(--wei-gold-deep); }

/* 右键 / 上下文菜单 */
.list-group {
  color: var(--wei-ink);
  background: rgba(255, 250, 238, 0.98);
  border-color: var(--wei-line-soft);
}
.list-group .list-group-item:hover { background: rgba(241, 197, 106, 0.18); }

/* gray-gate · 逐条关掉酒馆默认的灰/黑底（来源均为 SillyTavern 1.19 style.css） */

/* 1. 强调标题条：官方是 white30a→grey30a→black70a 渐变
      .standoutHeader / 扩展页抽屉头 / 用户设置 h4 */
#top-settings-holder .standoutHeader,
#left-nav-panel .standoutHeader,
#right-nav-panel .standoutHeader,
.popup .standoutHeader,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4 {
  color: var(--wei-gold-deep);
  background-color: transparent;
  background-image: linear-gradient(100deg, rgba(241, 197, 106, 0.28), rgba(255, 246, 226, 0.6) 55%, rgba(241, 197, 106, 0.12));
  border: 1px solid var(--wei-line);
  box-shadow: none;
  text-shadow: none;
}
#top-settings-holder .standoutHeader ~ .inline-drawer-content,
#left-nav-panel .standoutHeader ~ .inline-drawer-content,
#right-nav-panel .standoutHeader ~ .inline-drawer-content,
.popup .standoutHeader ~ .inline-drawer-content {
  background-color: rgba(255, 250, 238, 0.7);
  border-color: var(--wei-line-soft);
}

/* 2. 滑块旁的数字框（官方 black30a） */
.range-block-counter input,
.neo-range-input {
  color: var(--wei-gold-deep);
  background-color: var(--wei-field);
  border: 1px solid var(--wei-line);
  box-shadow: none;
  font-variant-numeric: tabular-nums;
}
.range-block-counter input:focus,
.neo-range-input:focus { outline: none; border-color: var(--wei-gold-bright); box-shadow: var(--wei-focus); }

/* 3. 用户设置里的 neo 滑块：官方整套 !important，深色轨道 + brightness(.75) + black50a 内阴影 */
.neo-range-slider {
  background: linear-gradient(90deg, #F1C56A, #D99A3A) !important;
  background-size: 100% 100% !important;
  box-shadow: none !important;
  filter: none !important;
  height: 4px !important;
}
.neo-range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: var(--wei-img-sun) center / contain no-repeat;
  box-shadow: var(--wei-glow);
}
.neo-range-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: var(--wei-img-sun) center / contain no-repeat;
}

/* 4. 下拉、文本框的全局默认（官方 black30a），主界面以外的地方也兜底 */
select,
.text_pole,
textarea:not(#send_textarea) {
  color: var(--wei-ink);
  background-color: var(--wei-field);
  border-color: var(--wei-line);
}
select option,
select option:not(:checked) { color: var(--wei-ink); background-color: var(--wei-field); }

/* 5. ⓘ / ? 小图标：官方 opacity .5 叠在杏白上发灰 */
.fa-circle-info.opacity50p,
.fa-circle-question.opacity50p,
.note-link-span,
.note-link-span-lrg {
  color: var(--wei-gold-bright);
  opacity: 1;
  filter: none;
}
.note-link-span:hover,
.fa-circle-info.opacity50p:hover { color: var(--wei-gold-deep); }

/* 6. 提示词排序条目（官方 black30a） */
.prompt_order > div {
  color: var(--wei-ink);
  background-color: var(--wei-field);
  border-color: var(--wei-line-soft);
}
.prompt_order > div:hover { background-color: rgba(241, 197, 106, 0.16); }

/* 7. 悬停：官方 white30a / menu_button 白雾 */
.select_chat_block:hover,
.swipe_picker_block:hover,
.bogus_folder_select:hover,
.avatar-container:hover { background-color: rgba(241, 197, 106, 0.16); }
.select_chat_block[highlight],
.swipe_picker_block[highlight] { background-color: rgba(241, 197, 106, 0.3); }
.menu_button:not(.disabled):not([disabled]):hover,
.menu_button:not(.disabled):not([disabled]).active {
  color: #FFFFFF;
  background-color: #E0A847;
  filter: none;
}
.menu_button { filter: none; }

/* 8. 遮罩与警告条 */
#shadow_popup,
#shadow_select_chat_popup,
#shadow_character_popup {
  background-color: rgba(120, 90, 40, 0.24);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
.reverse_proxy_warning:not(small) {
  background-color: rgba(241, 197, 106, 0.18);
  border-color: var(--wei-line);
}

/* 9. 快捷回复条：官方整条 opacity .7 */
#qr--bar { opacity: 1; }
#qr--bar .menu_button,
#qr--bar > #qr--popoutTrigger {
  color: var(--wei-gold-deep);
  background-color: var(--wei-surface-2);
  border: 1px solid var(--wei-line);
  border-radius: 999px;
  box-shadow: none;
  filter: none;
}

/* fallback · 字体加载失败回落楷体；图片均内嵌，不依赖外链 */
@supports not (mask-image: linear-gradient(#000, transparent)) {
  #chat .mes[is_user="true"]::before { opacity: 0.6; }
}
@media (prefers-reduced-motion: reduce) {
  #send_but::before,
  #top-settings-holder .drawer-icon { transition: none; }
}
